/**
 * base64url.mjs — hand-written base64url (RFC 4648 §5) codec.
 *
 * JOSE uses base64url *without* padding: the standard alphabet with "+" and "/"
 * swapped for "-" and "_", and every trailing "=" stripped. Everything here is
 * plain shifts and table lookups so the library stays dependency free — no
 * Buffer, no atob/btoa, no builtin modules.
 *
 * Encoding is the classic 3-bytes -> 4-characters grouping:
 *
 *   aaaaaaaa bbbbbbbb cccccccc   (24 bits)
 *   ^^^^^^ ^^^^^^ ^^^^^^ ^^^^^^  (4 x 6 bits -> 4 alphabet characters)
 *
 * A 1- or 2-byte tail produces 2 or 3 characters respectively; the "=" padding
 * that standard base64 would append is simply never emitted.
 *
 * Decoding mirrors python-jose's `base64url_decode`, which is deliberately
 * lenient: it re-adds whatever padding is missing before decoding. On top of
 * that we also accept the standard "+"/"/" alphabet, so a token produced by a
 * non-JOSE encoder still round-trips. Characters outside both alphabets are a
 * hard error.
 */

import { utf8Encode } from './bytes.mjs';

/** Number of source bytes per encoded group. */
const BYTES_PER_GROUP = 3;

/** Number of encoded characters per group. */
const CHARS_PER_GROUP = 4;

/** Bit width of one base64 symbol. */
const BITS_PER_CHAR = 6;

/** Mask for one base64 symbol (0b111111). */
const CHAR_MASK = 0x3f;

/** Flush the encoder accumulator this often so joins stay cheap. */
const OUTPUT_CHUNK_SIZE = 4096;

/**
 * Build the 64 character base64url alphabet: A-Z, a-z, 0-9, "-", "_".
 *
 * It is assembled from code points rather than written as a literal so the
 * ordering is provably the RFC 4648 one.
 *
 * @returns {string} the 64 character alphabet, index == 6-bit value
 */
function buildAlphabet() {
  let alphabet = '';
  for (let code = 0x41; code <= 0x5a; code += 1) {
    alphabet += String.fromCharCode(code); // 'A'..'Z' -> values 0..25
  }
  for (let code = 0x61; code <= 0x7a; code += 1) {
    alphabet += String.fromCharCode(code); // 'a'..'z' -> values 26..51
  }
  for (let code = 0x30; code <= 0x39; code += 1) {
    alphabet += String.fromCharCode(code); // '0'..'9' -> values 52..61
  }
  alphabet += '-'; // value 62 (standard base64 uses '+')
  alphabet += '_'; // value 63 (standard base64 uses '/')
  return alphabet;
}

/** The url-safe alphabet, indexed by 6-bit value. */
const ALPHABET = buildAlphabet();

/**
 * Build the reverse lookup table: character code -> 6-bit value, or -1 when the
 * character is not part of any accepted alphabet. Both the url-safe pair
 * ("-", "_") and the standard pair ("+", "/") map onto 62 and 63.
 *
 * @returns {Int8Array} 128 entry table covering the ASCII range
 */
function buildDecodeTable() {
  const table = new Int8Array(128).fill(-1);
  for (let value = 0; value < ALPHABET.length; value += 1) {
    table[ALPHABET.charCodeAt(value)] = value;
  }
  table['+'.charCodeAt(0)] = 62; // standard alphabet alias for '-'
  table['/'.charCodeAt(0)] = 63; // standard alphabet alias for '_'
  return table;
}

/** Character code -> 6-bit value (-1 for anything unaccepted). */
const DECODE_TABLE = buildDecodeTable();

/**
 * Encode bytes as unpadded base64url text.
 *
 * @param {Uint8Array|number[]} bytes input bytes
 * @returns {string} base64url text with no "=" padding
 */
export function base64UrlEncode(bytes) {
  const input = toByteArray(bytes);
  const length = input.length;
  const fullGroups = length - (length % BYTES_PER_GROUP);

  const pieces = [];
  let out = '';

  // Whole 3-byte groups: 24 bits in, 4 characters out.
  for (let i = 0; i < fullGroups; i += BYTES_PER_GROUP) {
    const group = (input[i] << 16) | (input[i + 1] << 8) | input[i + 2];
    out +=
      ALPHABET[(group >> 18) & CHAR_MASK] +
      ALPHABET[(group >> 12) & CHAR_MASK] +
      ALPHABET[(group >> BITS_PER_CHAR) & CHAR_MASK] +
      ALPHABET[group & CHAR_MASK];

    if (out.length >= OUTPUT_CHUNK_SIZE) {
      pieces.push(out);
      out = '';
    }
  }

  // Tail of 1 or 2 bytes. The unused low bits are zero, and no "=" is emitted.
  const remaining = length - fullGroups;
  if (remaining === 1) {
    const group = input[fullGroups] << 16;
    out += ALPHABET[(group >> 18) & CHAR_MASK] + ALPHABET[(group >> 12) & CHAR_MASK];
  } else if (remaining === 2) {
    const group = (input[fullGroups] << 16) | (input[fullGroups + 1] << 8);
    out +=
      ALPHABET[(group >> 18) & CHAR_MASK] +
      ALPHABET[(group >> 12) & CHAR_MASK] +
      ALPHABET[(group >> BITS_PER_CHAR) & CHAR_MASK];
  }

  pieces.push(out);
  return pieces.join('');
}

/**
 * Decode base64url (or standard base64) text back into bytes.
 *
 * Lenient in exactly the ways python-jose is:
 * - any amount of missing "=" padding is fine (the length simply implies it)
 * - trailing "=" padding, if present, is accepted and ignored
 * - both the "-_" and "+/" alphabets are understood
 * - surplus low bits in the final character are discarded rather than rejected
 *
 * Strict about everything else: any other character throws, and a length that
 * leaves a single leftover character (len % 4 == 1) is impossible to have come
 * from an encoder, so it throws too.
 *
 * @param {string|Uint8Array|number[]} str base64url text (or its ASCII bytes)
 * @returns {Uint8Array} the decoded bytes
 * @throws {Error} on characters outside the alphabet or an impossible length
 */
export function base64UrlDecode(str) {
  const codes = toCharCodes(str);

  // Drop trailing padding; "=" anywhere else is rejected by the table lookup.
  let end = codes.length;
  while (end > 0 && codes[end - 1] === 0x3d /* '=' */) {
    end -= 1;
  }

  const remainder = end % CHARS_PER_GROUP;
  if (remainder === 1) {
    // 6 bits cannot encode a whole byte, so no encoder can produce this.
    throw new Error('Invalid base64url string: length leaves a single trailing character.');
  }

  // Every 4 characters yield 3 bytes; a 2- or 3-character tail yields 1 or 2.
  const fullGroups = end - remainder;
  const outputLength = (fullGroups / CHARS_PER_GROUP) * BYTES_PER_GROUP + (remainder > 0 ? remainder - 1 : 0);
  const out = new Uint8Array(outputLength);

  let offset = 0;
  let accumulator = 0; // bit buffer, filled 6 bits at a time
  let bitsHeld = 0;

  for (let i = 0; i < end; i += 1) {
    const value = decodeChar(codes[i]);
    accumulator = (accumulator << BITS_PER_CHAR) | value;
    bitsHeld += BITS_PER_CHAR;

    // As soon as at least 8 bits are buffered, emit the top byte.
    if (bitsHeld >= 8) {
      bitsHeld -= 8;
      out[offset] = (accumulator >> bitsHeld) & 0xff;
      offset += 1;
    }
  }

  return out;
}

/**
 * Encode a JavaScript string as base64url by way of its UTF-8 bytes.
 *
 * @param {string} str text to encode
 * @returns {string} base64url text with no "=" padding
 */
export function base64UrlEncodeText(str) {
  return base64UrlEncode(utf8Encode(str));
}

/**
 * Translate one character code into its 6-bit value.
 *
 * @param {number} code ASCII character code
 * @returns {number} the 6-bit value 0..63
 * @throws {Error} when the character belongs to neither alphabet
 */
function decodeChar(code) {
  const value = code >= 0 && code < DECODE_TABLE.length ? DECODE_TABLE[code] : -1;
  if (value < 0) {
    throw new Error(`Invalid base64url character: ${describeCharCode(code)}`);
  }
  return value;
}

/**
 * Render a character code for an error message: printable ASCII is shown as
 * itself, anything else as an escaped code point.
 *
 * @param {number} code character code
 * @returns {string} human readable description
 */
function describeCharCode(code) {
  if (code >= 0x21 && code <= 0x7e) {
    return `'${String.fromCharCode(code)}'`;
  }
  const hex = code.toString(16).toLowerCase();
  return `U+${'0000'.slice(hex.length)}${hex}`.slice(0, 2 + Math.max(4, hex.length) + 0);
}

/**
 * Normalise an input into a Uint8Array without copying when possible.
 *
 * @param {Uint8Array|number[]|null|undefined} bytes input
 * @returns {Uint8Array} the bytes
 */
function toByteArray(bytes) {
  if (bytes instanceof Uint8Array) {
    return bytes;
  }
  return new Uint8Array(bytes || []);
}

/**
 * Normalise base64 input into a list of character codes. Strings are read code
 * unit by code unit; byte arrays (as produced by the ASCII-only token split)
 * are used as-is, since their values already are the character codes.
 *
 * @param {string|Uint8Array|number[]|null|undefined} input base64 text or bytes
 * @returns {Uint8Array|number[]} character codes
 */
function toCharCodes(input) {
  if (input instanceof Uint8Array) {
    return input;
  }
  if (Array.isArray(input)) {
    return input;
  }

  const text = typeof input === 'string' ? input : String(input === null || input === undefined ? '' : input);
  const codes = new Uint16Array(text.length);
  for (let i = 0; i < text.length; i += 1) {
    codes[i] = text.charCodeAt(i);
  }
  return codes;
}

