// Scratch cross-check for /output/lib/base64url.mjs (NOT a deliverable).
import { base64UrlEncode, base64UrlDecode, base64UrlEncodeText } from '/output/lib/base64url.mjs';

let failures = 0;
function check(label, actual, expected) {
  const ok = actual === expected;
  if (!ok) {
    failures += 1;
    console.log(`FAIL ${label}\n  actual  : ${JSON.stringify(actual)}\n  expected: ${JSON.stringify(expected)}`);
  }
  return ok;
}

// --- RFC 4648 §10 vectors (standard alphabet, padding stripped) -------------
const rfc = [
  ['', ''],
  ['f', 'Zg'],
  ['fo', 'Zm8'],
  ['foo', 'Zm9v'],
  ['foob', 'Zm9vYg'],
  ['fooba', 'Zm9vYmE'],
  ['foobar', 'Zm9vYmFy'],
];
for (const [text, expected] of rfc) {
  check(`rfc4648 encode ${JSON.stringify(text)}`, base64UrlEncodeText(text), expected);
}

// --- url-safe alphabet coverage: bytes that force '-' and '_' ---------------
// 0xfb 0xff -> '+/8' in standard base64 => '-_8' url-safe.
check('urlsafe chars', base64UrlEncode(new Uint8Array([0xfb, 0xff])), '-_8');
check('all 62/63 values', base64UrlEncode(new Uint8Array([0xff, 0xef, 0xbf])), '_--_');

// --- alphabet ordering: 0..63 as 6-bit values must render the alphabet ------
{
  const values = [];
  for (let v = 0; v < 64; v += 1) values.push(v);
  // pack 4 six-bit values into 3 bytes at a time
  const bytes = [];
  for (let i = 0; i < values.length; i += 4) {
    const g = (values[i] << 18) | (values[i + 1] << 12) | (values[i + 2] << 6) | values[i + 3];
    bytes.push((g >> 16) & 0xff, (g >> 8) & 0xff, g & 0xff);
  }
  check(
    'alphabet order',
    base64UrlEncode(new Uint8Array(bytes)),
    'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_'
  );
}

// --- round-trip every length 0..300 with pseudo-random bytes ----------------
let seed = 123456789;
function nextByte() {
  seed = (seed * 1103515245 + 12345) & 0x7fffffff;
  return (seed >> 16) & 0xff;
}
for (let len = 0; len <= 300; len += 1) {
  const src = new Uint8Array(len);
  for (let i = 0; i < len; i += 1) src[i] = nextByte();
  const enc = base64UrlEncode(src);
  if (/[=+/]/.test(enc)) {
    failures += 1;
    console.log(`FAIL padding/alphabet leak at len ${len}: ${enc}`);
  }
  const back = base64UrlDecode(enc);
  check(`roundtrip len ${len}`, Array.from(back).join(','), Array.from(src).join(','));
  // cross-check against Node's own base64url (scratch-only sanity oracle)
  check(`vs node len ${len}`, enc, Buffer.from(src).toString('base64url'));
}

